#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/binding/binding_source/binding_source.hpp"

#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// BindingNavigator's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/binding_navigator.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The source the navigator moves through, or null (Windows Forms' BindingSource). A write subscribes to the new source's list, position and disposal and shows its position and count at once; the source's disposal clears it.
template <typename Declaring>
struct BindingNavigatorBindingSourceCapability {
    PropertyView<std::shared_ptr<BindingSource>, BindingNavigatorBindingSourceCapability<Declaring>> binding_source;

    static void assign(BindingNavigatorBindingSourceCapability& capability, std::shared_ptr<BindingSource> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.binding_source), std::move(incoming));
    }

    static std::shared_ptr<BindingSource> read(const BindingNavigatorBindingSourceCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::shared_ptr<BindingSource> current = control.read_view(capability.binding_source);
        return current;
    }
};

// Every BindingNavigator capability, in the order the declaring class takes them.
template <typename Declaring>
struct BindingNavigatorCapabilities : public BindingNavigatorBindingSourceCapability<Declaring> {};

} // namespace gui_forms
